'use strict'

/* global describe, test, expect */

const {
  parseCacheControlHeader,
  hasInvalidCacheControlDirective,
  parseVaryHeader,
  hasVaryStar,
  isInvalidOrWildcardVaryHeader,
  isEtagUsable
} = require('../../../lib/util/cache')

describe('lib/util/cache parseCacheControlHeader', () => {
  test('parses common directives and ignores unknown ones', () => {
    expect(parseCacheControlHeader('max-age=60, public, no-store, unknown-directive=value')).toEqual({
      'max-age': 60,
      public: true,
      'no-store': true
    })
  })

  test('accepts an array of header values', () => {
    expect(parseCacheControlHeader(['max-age=60', 'public'])).toEqual({
      'max-age': 60,
      public: true
    })
  })

  test('is case-insensitive and trims optional whitespace', () => {
    expect(parseCacheControlHeader('MAX-AGE=30, Public, NO-CACHE')).toEqual({
      'max-age': 30,
      public: true,
      'no-cache': true
    })
  })

  test('keeps the least restrictive max-age and the most demanding min-fresh', () => {
    expect(parseCacheControlHeader('max-age=100, max-age=50')).toEqual({ 'max-age': 50 })
    expect(parseCacheControlHeader('min-fresh=10, min-fresh=20')).toEqual({ 'min-fresh': 20 })
  })

  test('parses quoted numeric directive values', () => {
    expect(parseCacheControlHeader('max-age="120"')).toEqual({ 'max-age': 120 })
    expect(parseCacheControlHeader('s-maxage="30"')).toEqual({ 's-maxage': 30 })
  })

  test('caps numeric deltas at the maximum signed 32-bit integer', () => {
    expect(parseCacheControlHeader('max-age=99999999999999')).toEqual({ 'max-age': 2147483647 })
  })

  test('marks invalid numeric directive values and ignores later duplicates', () => {
    const directives = parseCacheControlHeader('max-age=abc, max-age=60')

    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('rejects numeric values with whitespace around the equals sign', () => {
    const keyWithSpace = parseCacheControlHeader('max-age =60')
    const valueWithSpace = parseCacheControlHeader('max-age= 60')

    expect(keyWithSpace).toEqual({})
    expect(valueWithSpace).toEqual({})
    expect(hasInvalidCacheControlDirective(keyWithSpace, 'max-age')).toBe(true)
    expect(hasInvalidCacheControlDirective(valueWithSpace, 'max-age')).toBe(true)
  })

  test('marks a numeric directive without a value as invalid', () => {
    const directives = parseCacheControlHeader('max-stale')

    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-stale')).toBe(true)
  })

  test('reports false for directives that are absent or valid', () => {
    expect(hasInvalidCacheControlDirective(parseCacheControlHeader('max-age=60'), 'max-age')).toBe(false)
    expect(hasInvalidCacheControlDirective(parseCacheControlHeader('public'), 'max-age')).toBe(false)
  })

  test('parses unqualified private and no-cache as booleans', () => {
    expect(parseCacheControlHeader('private, no-cache')).toEqual({
      private: true,
      'no-cache': true
    })
  })

  test('parses qualified no-cache and private header lists', () => {
    expect(parseCacheControlHeader('no-cache=foo')).toEqual({ 'no-cache': ['foo'] })
    expect(parseCacheControlHeader('no-cache="set-cookie, x-trace"')).toEqual({
      'no-cache': ['set-cookie', 'x-trace']
    })
    expect(parseCacheControlHeader('private="set-cookie"')).toEqual({ private: ['set-cookie'] })
  })

  test('merges repeated qualified no-cache directives', () => {
    expect(parseCacheControlHeader('no-cache="a", no-cache="b"')).toEqual({
      'no-cache': ['a', 'b']
    })
  })

  test('treats an invalid no-cache field list as an unqualified directive', () => {
    expect(parseCacheControlHeader('no-cache="bad header"')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('no-cache="a, "')).toEqual({ 'no-cache': true })
  })

  test('rejects malformed quoted directive values', () => {
    const directives = parseCacheControlHeader('max-age="60, public')

    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('drops every instance of a no-argument directive that is given a value', () => {
    expect(parseCacheControlHeader('public=1, public')).toEqual({})
    expect(parseCacheControlHeader('must-revalidate=1, immutable=2')).toEqual({})
  })

  test('handles malformed restrictive directive names as unqualified directives', () => {
    expect(parseCacheControlHeader('no-cache@x, max-age=5')).toEqual({
      'no-cache': true,
      'max-age': 5
    })
    expect(parseCacheControlHeader('no-store[foo]')).toEqual({ 'no-store': true })
    expect(parseCacheControlHeader('private;x')).toEqual({ private: true })
  })

  test('treats no-store with a value as no-store', () => {
    expect(parseCacheControlHeader('no-store=1')).toEqual({ 'no-store': true })
  })
})

describe('lib/util/cache Vary header helpers', () => {
  test('hasVaryStar detects a placeholder in string and array values', () => {
    expect(hasVaryStar('Accept, *')).toBe(true)
    expect(hasVaryStar('*')).toBe(true)
    expect(hasVaryStar(['Accept', '  *  '])).toBe(true)
    expect(hasVaryStar('Accept-Encoding')).toBe(false)
    expect(hasVaryStar([])).toBe(false)
  })

  test('parseVaryHeader lowercases names and selects request header values', () => {
    expect(parseVaryHeader('Accept, Accept-Encoding', {
      accept: 'text/html',
      'accept-encoding': ['gzip', 'br']
    })).toEqual({
      accept: 'text/html',
      'accept-encoding': ['gzip', 'br']
    })
  })

  test('parseVaryHeader records missing request headers as null', () => {
    expect(parseVaryHeader('Accept, X-Missing', { accept: 'text/html' })).toEqual({
      accept: 'text/html',
      'x-missing': null
    })
  })

  test('parseVaryHeader copies array-valued request headers', () => {
    const accept = ['text/html', 'application/json']
    const parsed = parseVaryHeader('Accept', { accept })

    expect(parsed.accept).toEqual(accept)
    expect(parsed.accept).not.toBe(accept)
  })

  test('parseVaryHeader returns the request headers object for a wildcard', () => {
    const headers = { accept: 'text/html' }
    expect(parseVaryHeader('Accept, *', headers)).toBe(headers)
  })

  test('parseVaryHeader skips empty entries and rejects invalid header names', () => {
    expect(parseVaryHeader('Accept, , Accept-Encoding', { accept: 'text/plain', 'accept-encoding': 'gzip' })).toEqual({
      accept: 'text/plain',
      'accept-encoding': 'gzip'
    })
    expect(parseVaryHeader('Accept, bad header', { accept: 'text/plain' })).toBeUndefined()
  })

  test('isInvalidOrWildcardVaryHeader distinguishes wildcard, invalid, and valid headers', () => {
    expect(isInvalidOrWildcardVaryHeader('*')).toBe(true)
