    expect(isInvalidOrWildcardVaryHeader('Accept, bad header')).toBe(true)
    expect(isInvalidOrWildcardVaryHeader('Accept, Accept-Encoding')).toBe(false)
    expect(isInvalidOrWildcardVaryHeader('')).toBe(false)
  })
})

