    })
  })

  test('copies array header values instead of modifying the input', () => {
    const original = ['a', 'b']
    const normalized = normalizeHeaders({ headers: { 'x-multi': original } })

    expect(normalized['x-multi']).toEqual(['a', 'b'])
    expect(normalized['x-multi']).not.toBe(original)
    original.push('c')
    expect(normalized['x-multi']).toEqual(['a', 'b'])
  })

  test('accepts a flat alternating key/value array', () => {
    expect(normalizeHeaders({ headers: ['X-A', 'one', 'x-a', 'two'] })).toEqual({
      'x-a': ['one', 'two']
    })
  })

  test('accepts an array of header pairs', () => {
    expect(normalizeHeaders({ headers: [['X-A', 'one'], ['X-B', 'two']] })).toEqual({
      'x-a': 'one',
      'x-b': 'two'
    })
  })

  test('accepts a non-array iterable of header pairs', () => {
    expect(normalizeHeaders({ headers: new Map([['X-A', 'one'], ['X-B', 'two']]) })).toEqual({
      'x-a': 'one',
      'x-b': 'two'
    })
  })

  test('converts Buffer values in flat arrays to latin1 strings', () => {
    expect(normalizeHeaders({ headers: ['x-buffer', [Buffer.from('hi')]] })).toEqual({
      'x-buffer': ['hi']
    })
  })

  test('rejects non-object headers', () => {
    expect(() => normalizeHeaders({ headers: 'accept: text/plain' })).toThrow('opts.headers is not an object')
  })

  test('rejects malformed flat arrays', () => {
    expect(() => normalizeHeaders({ headers: ['x-a'] })).toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: ['x-a', 1] })).toThrow('opts.headers is not a valid header map')
  })

  test('rejects malformed header pair arrays and iterables', () => {
    expect(() => normalizeHeaders({ headers: [['x-a']] })).toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: [[1, 'one']] })).toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: [['x-a', 1]] })).toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: [['x-a', 'one'], 'x-b'] })).toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: new Set(['x-a']) })).toThrow('opts.headers is not a valid header map')
  })

  test('stores a __proto__ header as an own data property', () => {
    const normalized = normalizeHeaders({ headers: JSON.parse('{"__proto__":"value"}') })

    expect(Object.hasOwn(normalized, '__proto__')).toBe(true)
    expect(Object.getOwnPropertyDescriptor(normalized, '__proto__').value).toBe('value')
    expect(Object.getPrototypeOf(normalized)).toBe(Object.prototype)
  })
})

describe('lib/util/cache assertions', () => {
  test('assertCacheKey accepts a well-formed key', () => {
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET', path: '/' })).not.toThrow()
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET', path: '/', headers: {} })).not.toThrow()
  })

  test('assertCacheKey rejects non-objects and missing string fields', () => {
    expect(() => assertCacheKey('key')).toThrow('expected key to be object, got string')
    expect(() => assertCacheKey({ method: 'GET', path: '/' })).toThrow('expected key.origin to be string, got undefined')
    expect(() => assertCacheKey({ origin: 'http://example.com', path: '/' })).toThrow('expected key.method to be string, got undefined')
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET' })).toThrow('expected key.path to be string, got undefined')
  })

  test('assertCacheKey rejects non-object headers', () => {
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET', path: '/', headers: 'bad' }))
      .toThrow('expected headers to be object, got object')
  })

  test('assertCacheValue accepts a well-formed value', () => {
    expect(() => assertCacheValue({
      statusCode: 200,
      statusMessage: 'OK',
      cachedAt: 1,
      staleAt: 2,
      deleteAt: 3,
      headers: { 'content-type': 'text/plain' },
      vary: { accept: 'text/plain' },
      etag: '"abc"'
    })).not.toThrow()
  })

  test('assertCacheValue rejects missing or wrongly typed required fields', () => {
    expect(() => assertCacheValue({})).toThrow('expected value.statusCode to be number, got undefined')
    expect(() => assertCacheValue({
      statusCode: 200,
      cachedAt: 1,
      staleAt: 2,
      deleteAt: 3,
      statusMessage: 1
    })).toThrow('expected value.statusMessage to be string, got number')
    expect(() => assertCacheValue({
      statusCode: 200,
      cachedAt: '1',
      staleAt: 2,
      deleteAt: 3,
      statusMessage: 'OK'
    })).toThrow('expected value.cachedAt to be number, got string')
  })

  test('assertCacheValue validates optional fields when present', () => {
    const base = { statusCode: 200, cachedAt: 1, staleAt: 2, deleteAt: 3, statusMessage: 'OK' }
    expect(() => assertCacheValue({ ...base, headers: 'bad' })).toThrow('expected value.rawHeaders to be object, got string')
    expect(() => assertCacheValue({ ...base, vary: 'accept' })).toThrow('expected value.vary to be object, got string')
    expect(() => assertCacheValue({ ...base, etag: 123 })).toThrow('expected value.etag to be string, got number')
  })

  test('assertCacheStore accepts an object implementing the store contract', () => {
    expect(() => assertCacheStore({
      get () {},
      createWriteStream () {},
      delete () {}
    })).not.toThrow()
  })

  test('assertCacheStore rejects missing stores and methods', () => {
    expect(() => assertCacheStore(null)).toThrow('expected type of CacheStore to be a CacheStore, got null')
    expect(() => assertCacheStore('store')).toThrow('expected type of CacheStore to be a CacheStore, got string')
    expect(() => assertCacheStore({})).toThrow('CacheStore needs to have a `get()` function')
    expect(() => assertCacheStore({ get () {} })).toThrow('CacheStore needs to have a `createWriteStream()` function')
    expect(() => assertCacheStore({ get () {}, createWriteStream () {} })).toThrow('CacheStore needs to have a `delete()` function')
    expect(() => assertCacheStore({}, 'CustomStore')).toThrow('CustomStore needs to have a `get()` function')
  })

  test('assertCacheMethods accepts all safe HTTP methods', () => {
    expect(() => assertCacheMethods(['GET'])).not.toThrow()
    expect(() => assertCacheMethods(['GET', 'HEAD', 'OPTIONS', 'TRACE'])).not.toThrow()
  })

  test('assertCacheMethods rejects non-arrays, empty arrays, and unsafe methods', () => {
    expect(() => assertCacheMethods('GET')).toThrow('expected type of CacheMethods needs to be an array, got string')
    expect(() => assertCacheMethods([])).toThrow('CacheMethods needs to have at least one method')
    expect(() => assertCacheMethods(['GET', 'POST'])).toThrow('element of CacheMethods-array needs to be one of following values: GET, HEAD, OPTIONS, TRACE, got POST')
    expect(() => assertCacheMethods(['get'], 'Methods')).toThrow('element of Methods-array needs to be one of following values: GET, HEAD, OPTIONS, TRACE, got get')
  })
})

describe('lib/util/cache makeDeduplicationKey', () => {
  test('produces a stable JSON key with sorted header names', () => {
    const keyA = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { b: '2', A: '1', 'x-test': 'z' }
    })
    const keyB = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { 'x-test': 'z', A: '1', b: '2' }
    })

    expect(keyA).toBe(keyB)
    expect(JSON.parse(keyA)).toEqual(['http://example.com', 'GET', '/', { A: '1', b: '2', 'x-test': 'z' }])
  })

  test('excludes requested headers case-insensitively', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { Accept: 'text/plain', 'X-Trace': 'abc' }
    }, new Set(['x-trace']))

    expect(JSON.parse(key)[3]).toEqual({ Accept: 'text/plain' })
  })

  test('uses an empty header object when no headers are supplied', () => {
    expect(makeDeduplicationKey({ origin: 'http://example.com', method: 'GET', path: '/' }))
      .toBe(JSON.stringify(['http://example.com', 'GET', '/', {}]))
  })

  test('preserves array-valued headers', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { accept: ['text/plain', 'text/html'] }
    })

    expect(JSON.parse(key)[3]).toEqual({ accept: ['text/plain', 'text/html'] })
  })

  test('does not collide when header contents contain delimiters', () => {
    const keyA = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: 'x:b=y' }
    })
    const keyB = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: 'x', b: 'y' }
    })

    expect(keyA).not.toBe(keyB)
  })
})

'use strict'

/* global describe, test, expect */

const { parseHttpDate } = require('../../../lib/util/date')

describe('lib/util/date parseHttpDate', () => {
  describe('IMF-fixdate', () => {
    test('parses the preferred HTTP date format', () => {
      const date = parseHttpDate('Sun, 06 Nov 1994 08:49:37 GMT')

      expect(date).toBeInstanceOf(Date)
      expect(date.toISOString()).toBe('1994-11-06T08:49:37.000Z')
    })

    test('validates the weekday against the calendar date', () => {
      expect(parseHttpDate('Mon, 06 Nov 1994 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 07 Nov 1994 08:49:37 GMT')).toBeUndefined()
    })

    test('accepts leap days and rejects non-leap February 29', () => {
      expect(parseHttpDate('Tue, 29 Feb 2000 12:34:56 GMT').toISOString()).toBe('2000-02-29T12:34:56.000Z')
      expect(parseHttpDate('Tue, 29 Feb 1999 12:34:56 GMT')).toBeUndefined()
    })

    test('preserves years below 100 without mapping them to the 1900s', () => {
      expect(parseHttpDate('Mon, 01 Jan 0001 00:00:00 GMT').toISOString()).toBe('0001-01-01T00:00:00.000Z')
    })

    test('rejects out-of-range dates and times', () => {
      expect(parseHttpDate('Sun, 00 Nov 1994 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 32 Nov 1994 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 31 Feb 1994 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 Nov 1994 24:00:00 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 Nov 1994 23:60:00 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 Nov 1994 23:59:60 GMT')).toBeUndefined()
    })

    test('rejects malformed field separators and suffixes', () => {
      expect(parseHttpDate('Sun, 06 Nov 1994 08:49:37 UTC')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 Nov 1994 08:49:37')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 Nov 1994 08:49:37 GMT ')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 Nov 1994  08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 Nov 1994 08:49:37 gmt')).toBeUndefined()
    })

    test('rejects invalid month and year spellings', () => {
      expect(parseHttpDate('Sun, 06 Foo 1994 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 nov 1994 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 Nov 19x4 08:49:37 GMT')).toBeUndefined()
    })
  })

  describe('ANSI C asctime() format', () => {
    test('parses a valid asctime date', () => {
      expect(parseHttpDate('Sun Nov  6 08:49:37 1994').toISOString()).toBe('1994-11-06T08:49:37.000Z')
      expect(parseHttpDate('Mon Nov  7 08:49:37 1994').toISOString()).toBe('1994-11-07T08:49:37.000Z')
    })

    test('requires the double-space padding before a single-digit day', () => {
      expect(parseHttpDate('Sun Nov 6 08:49:37 1994')).toBeUndefined()
    })

    test('validates the weekday and time components', () => {
      expect(parseHttpDate('Mon Nov  6 08:49:37 1994')).toBeUndefined()
      expect(parseHttpDate('Sun Nov  6 24:00:00 1994')).toBeUndefined()
    })

    test('handles single-digit years through the shared calendar validation', () => {
      expect(parseHttpDate('Mon Jan  1 00:00:00 0001').toISOString()).toBe('0001-01-01T00:00:00.000Z')
    })

    test('rejects values with an incorrect length or trailing data', () => {
      expect(parseHttpDate('Sun Nov  6 08:49:37 1994 ')).toBeUndefined()
    })
  })

  describe('obsolete RFC 850 format', () => {
    test('parses two-digit years and expands them using the 1970-2069 window', () => {
      expect(parseHttpDate('Sunday, 06-Nov-94 08:49:37 GMT').toISOString()).toBe('1994-11-06T08:49:37.000Z')
      expect(parseHttpDate('Monday, 06-Nov-00 08:49:37 GMT').toISOString()).toBe('2000-11-06T08:49:37.000Z')
      expect(parseHttpDate('Wednesday, 06-Nov-69 08:49:37 GMT').toISOString()).toBe('2069-11-06T08:49:37.000Z')
      expect(parseHttpDate('Friday, 06-Nov-70 08:49:37 GMT').toISOString()).toBe('1970-11-06T08:49:37.000Z')
      expect(parseHttpDate('Saturday, 06-Nov-99 08:49:37 GMT').toISOString()).toBe('1999-11-06T08:49:37.000Z')
    })

    test('validates the weekday and two-digit year length', () => {
      expect(parseHttpDate('Monday, 06-Nov-94 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sunday, 06-Nov-1994 08:49:37 GMT')).toBeUndefined()
    })

    test('rejects malformed separators, months, suffix, and calendar dates', () => {
      expect(parseHttpDate('Sunday 06-Nov-94 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sunday, 06-Foo-94 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sunday, 06-Nov-94 08:49:37 UTC')).toBeUndefined()
      expect(parseHttpDate('Sunday, 31-Feb-99 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sunday, 06-Nov-94 24:00:00 GMT')).toBeUndefined()
    })
  })

  describe('invalid input', () => {
    test('returns undefined for empty and malformed strings', () => {
      expect(parseHttpDate('')).toBeUndefined()
      expect(parseHttpDate('not a date')).toBeUndefined()
      expect(parseHttpDate('1234')).toBeUndefined()
      expect(parseHttpDate('Funday, 06-Nov-94 08:49:37 GMT')).toBeUndefined()
    })
  })
})

'use strict'

/* global describe, test, expect, afterEach */

const runtimeFeaturesModule = require('../../../lib/util/runtime-features')

describe('lib/util/runtime-features', () => {
  const { runtimeFeatures, default: defaultExport } = runtimeFeaturesModule

  afterEach(() => {
    runtimeFeatures.clear()
  })

  test('exports a single shared runtime feature detector', () => {
    expect(runtimeFeatures).toBe(defaultExport)
    expect(typeof runtimeFeatures.has).toBe('function')
    expect(typeof runtimeFeatures.set).toBe('function')
    expect(typeof runtimeFeatures.clear).toBe('function')
  })

  test('detects features that are available in the current Node.js runtime', () => {
    expect(runtimeFeatures.has('crypto')).toBe(true)
    expect(runtimeFeatures.has('sqlite')).toBe(true)
  })

  test('reports unknown features through a TypeError', () => {
    expect(() => runtimeFeatures.has('worker_threads')).toThrow(new TypeError('unknown feature: worker_threads'))
  })

  test('allows overriding a detected feature', () => {
    runtimeFeatures.set('crypto', false)
    expect(runtimeFeatures.has('crypto')).toBe(false)

    runtimeFeatures.set('crypto', true)
    expect(runtimeFeatures.has('crypto')).toBe(true)
  })

  test('clear removes both detections and overrides', () => {
    runtimeFeatures.set('crypto', false)
    runtimeFeatures.set('sqlite', false)

    runtimeFeatures.clear()

    expect(runtimeFeatures.has('crypto')).toBe(true)
    expect(runtimeFeatures.has('sqlite')).toBe(true)
  })

  test('rejects setting an unknown feature', () => {
    expect(() => runtimeFeatures.set('worker_threads', true)).toThrow(new TypeError('unknown feature: worker_threads'))
  })

  test('clear is safe to call repeatedly', () => {
    expect(() => {
      runtimeFeatures.clear()
      runtimeFeatures.clear()
    }).not.toThrow()
  })
})

