const { ClientStats, PoolStats } = require('../../../lib/util/stats')
const {
  kConnected,
  kPending,
  kRunning,
  kSize,
  kFree,
  kQueued
} = require('../../../lib/core/symbols')

describe('lib/util/stats ClientStats', () => {
  test('copies the observable client counters', () => {
    const client = {
      [kConnected]: 3,
      [kPending]: 4,
      [kRunning]: 2,
      [kSize]: 9
    }

    const stats = new ClientStats(client)

    expect(stats).toEqual({
      connected: 3,
      pending: 4,
      running: 2,
      size: 9
    })
  })

  test('takes a snapshot of the client counters', () => {
    const client = {
      [kConnected]: 1,
      [kPending]: 2,
      [kRunning]: 3,
      [kSize]: 4
    }
    const stats = new ClientStats(client)

    client[kConnected] = 10
    client[kPending] = 20
    client[kRunning] = 30
    client[kSize] = 40

    expect(stats).toEqual({
      connected: 1,
      pending: 2,
      running: 3,
      size: 4
    })
  })

  test('leaves unavailable counters undefined', () => {
    const stats = new ClientStats({})

    expect(stats.connected).toBeUndefined()
    expect(stats.pending).toBeUndefined()
    expect(stats.running).toBeUndefined()
    expect(stats.size).toBeUndefined()
  })
